import { OneHandedPlaySetting } from '@game-studio/cabinet';
import { SettingsEventEmitter } from '@game-studio/settings';
import { mapChatSizeToNumber } from '@game-studio/utilities';

import { gameConfig } from '../../models/config-model';
import { inversifyContainer } from '../../inversify/container';
import { useCompanionState } from '../../models/companion-state';
import { sessionDataModel } from '../../models/session-data';
import { userPreferences } from '../../models/user-preferences';
import { eventEmitter } from '../../services/event-emitter';

import { ChatSizeOption } from '../../types';
import { chatColoursBackup } from './chat-colours';
import { ISettingsConfigs } from './types';

export function getSettingsConfig(): ISettingsConfigs {
    const settingsConfigs: ISettingsConfigs = {
        navigation: {
            howToPlay: {
                label: inversifyContainer.strings.settings.PREFERENCES.HOW_TO_PLAY,
                onClick: () => {
                    if (gameConfig.features.newStyleHTP) {
                        SettingsEventEmitter.emit('hide');
                        eventEmitter.emit('POPUP_TOGGLE_HTP_POPUP', true, 'settings');
                    } else {
                        eventEmitter.emit('POPUP_TOGGLE_OLD_HTP', true);
                    }
                }
            }
        },
        userPrefs: {
            sound: {
                type: 'checkbox',
                key: 'sound',
                label: inversifyContainer.strings.settings.PREFERENCES.SOUND_ON,
                default: userPreferences.sound,
                onClick: (val: boolean) => {
                    userPreferences.update({ sound: val });

                    if (!gameConfig.features.seperateMusicSoundControls) {
                        userPreferences.update({ music: val });
                    }
                }
            },
            music: {
                type: 'checkbox',
                key: 'music',
                label: inversifyContainer.strings.settings.PREFERENCES.MUSIC_ON,
                default: userPreferences.music,
                onClick: (val: boolean) => {
                    userPreferences.update({ music: val });
                }
            },
            chatSize: {
                type: 'radio',
                key: 'chatsize',
                label: inversifyContainer.strings.settings.PREFERENCES.CHAT_SIZE,
                default: userPreferences.chatSize,
                options: [
                    { text: inversifyContainer.strings.settings.PREFERENCES.CHAT_SIZE_OPTIONS.SMALL, value: 'small' },
                    { text: inversifyContainer.strings.settings.PREFERENCES.CHAT_SIZE_OPTIONS.MEDIUM, value: 'medium' },
                    { text: inversifyContainer.strings.settings.PREFERENCES.CHAT_SIZE_OPTIONS.LARGE, value: 'large' },
                ],
                onClick: (val: ChatSizeOption) => {
                    userPreferences.update({ chatsize: mapChatSizeToNumber(val) });
                    inversifyContainer.frameConnection.chat.setChatSize({ size: val });
                }
            },
            chatColour: {
                type: 'colour',
                key: 'chatcolour',
                label: inversifyContainer.strings.settings.PREFERENCES.CHAT_COLOUR,
                default: userPreferences.chatColour,
                options: chatColoursBackup,
                onClick: (val: string) => {
                    const companionState = useCompanionState();
                    const colours = companionState.chatColours.value.length > 0 ? companionState.chatColours.value : chatColoursBackup;
                    colours.forEach((colour, index) => {
                        if (colour.value === val) {
                            userPreferences.update({ chatcolour: index as number });
                            inversifyContainer.frameConnection.chat.setChatColour({ colour: val });
                        }
                    });
                }
            },
            notifications: {
                type: 'checkbox',
                key: 'notifications',
                label: inversifyContainer.strings.settings.PREFERENCES.INGAME_NOTIFICATIONS,
                default: userPreferences.notifications,
                onClick: (val: boolean) => {
                    userPreferences.update({ notifications: val });
                }
            },
            oneHandedPlay: {
                type: 'radio',
                key: 'oneHandedPlay',
                label: inversifyContainer.strings.settings.PREFERENCES.ONE_HANDED_PLAY,
                default: userPreferences.oneHandedPlay,
                options: [
                    { text: inversifyContainer.strings.settings.PREFERENCES.ONE_HANDED_PLAY_OPTIONS.LEFT, value: OneHandedPlaySetting.left },
                    { text: inversifyContainer.strings.settings.PREFERENCES.ONE_HANDED_PLAY_OPTIONS.RIGHT, value: OneHandedPlaySetting.right }
                ],
                onClick: (val: OneHandedPlaySetting) => {
                    inversifyContainer.cabinet.changeCabinetLayout(val);
                    eventEmitter.emit('GLOBAL_ONE_HANDED_SETTING_CHANGED');
                    userPreferences.update({ oneHandedPlay: val });
                }
            },
            colourBlindMode: {
                type: 'checkbox',
                key: 'colourBlindMode',
                label: inversifyContainer.strings.settings.PREFERENCES.COLOUR_BLIND_MODE,
                default: userPreferences.colourBlindMode,
                onClick: (val: boolean) => {
                    userPreferences.update({ colourBlindMode: val });
                }
            },
        },
        subMenus: {
            recentWinners: {
                label: inversifyContainer.strings.settings.PREFERENCES.RECENT_WINNERS,
                value: inversifyContainer.strings.settings.PREFERENCES.RECENT_WINNERS
            },
            gameRules: {
                label: inversifyContainer.strings.settings.PREFERENCES.GAME_RULES,
                value: inversifyContainer.strings.settings.PREFERENCES.GAME_RULES,
            },
            chatRules: {
                label: inversifyContainer.strings.settings.PREFERENCES.CHAT_RULES,
                value: inversifyContainer.strings.settings.PREFERENCES.CHAT_RULES,
            }
        },
        labels: {
            sessionNumber: {
                label: inversifyContainer.strings.settings.SESSION_INFO?.SESSION_NUMBER || '',
                value: sessionDataModel.settingsText.sessionId.text
            },
            gameNumber: {
                label: inversifyContainer.strings.settings.SESSION_INFO?.GAME_NUMBER || '',
                value: sessionDataModel.settingsText.ticketId.text
            }
        },
        version: {
            label: inversifyContainer.strings.settings.VERSION ?? 'version',
            value: gameConfig.version
        }
    };
    return settingsConfigs;
}